// Vercel Edge Function: forwards /api/* to the meeting host and adds the shared edge key.
//
// Environment (set in the Vercel project, never in the page):
//   BACKEND_URL    https origin of the tunnel to the meeting host, no path
//   OTR_EDGE_KEY   shared secret the backend checks in X-OTR-Edge-Key
//
// vercel.json (generated by build.py when OTR_EDGE_KEY is configured) rewrites
// /api/:path* to /api/proxy?__otr_path=:path*. This function does not log request or
// response bodies, headers or cookies. Server-sent events do not survive this hop:
// the page keeps polling /api/me?summary=1 instead of opening /stream.

export const config = { runtime: "edge" };

// Request headers the backend needs. Everything else (including any client-supplied
// X-OTR-Edge-Key) is dropped, so the edge key can only come from this function.
const FORWARD = ["cookie", "content-type", "accept", "origin", "referer", "user-agent",
                 "x-requested-with"];
const SAFE_PATH = /^[A-Za-z0-9_\-./]+$/;

function target(request, backend) {
  const url = new URL(request.url);
  const given = url.searchParams.getAll("__otr_path");
  let path;
  if (given.length === 1) path = given[0];
  else if (given.length === 0 && url.pathname.startsWith("/api/") && url.pathname !== "/api/proxy")
    path = url.pathname.slice("/api/".length);
  else return null;
  path = path.replace(/^\/+/, "");
  if (!path || !SAFE_PATH.test(path) || path.split("/").some((p) => p === ".." || p === "." || p === "")
      || path.startsWith("_internal")) return null;
  url.searchParams.delete("__otr_path");
  const query = url.searchParams.toString();
  return backend + "/api/" + path + (query ? "?" + query : "");
}

export default async function handler(request) {
  const backend = (process.env.BACKEND_URL || "").replace(/\/+$/, "");
  const key = process.env.OTR_EDGE_KEY || "";
  if (!/^https:\/\/[^/]+$/.test(backend) || !key) {
    return new Response(JSON.stringify({ detail: "Proxy is not configured" }),
      { status: 500, headers: { "content-type": "application/json", "cache-control": "no-store" } });
  }
  const dest = target(request, backend);
  if (!dest) {
    return new Response(JSON.stringify({ detail: "Bad path" }),
      { status: 400, headers: { "content-type": "application/json", "cache-control": "no-store" } });
  }
  const headers = new Headers();
  for (const name of FORWARD) {
    const value = request.headers.get(name);
    if (value) headers.set(name, value);
  }
  headers.set("x-otr-edge-key", key);
  headers.set("ngrok-skip-browser-warning", "1");
  const method = request.method.toUpperCase();
  const init = { method, headers, redirect: "manual" };
  if (method !== "GET" && method !== "HEAD") {
    init.body = request.body;
    init.duplex = "half";
  }
  let upstream;
  try {
    upstream = await fetch(dest, init);
  } catch (_err) {
    return new Response(JSON.stringify({ detail: "Meeting host unreachable" }),
      { status: 502, headers: { "content-type": "application/json", "cache-control": "no-store" } });
  }
  const out = new Headers();
  for (const name of ["content-type", "cache-control", "location"]) {
    const value = upstream.headers.get(name);
    if (value) out.set(name, value);
  }
  // Session cookies must reach the browser unchanged, one header each.
  const cookies = typeof upstream.headers.getSetCookie === "function" ? upstream.headers.getSetCookie() : [];
  for (const cookie of cookies) out.append("set-cookie", cookie);
  out.set("cache-control", "no-store");
  return new Response(upstream.body, { status: upstream.status, headers: out });
}
